$ErrorActionPreference='Stop'
$python=[Text.Encoding]::ASCII.GetString([Convert]::FromBase64String(''))
'BUMBLEBEE: MYTH; HONOR MEDAL; MERIT; WINGS; RUNES; LASU_SAGLABAJUMUS_UN_LIMITUS'
$text=($python | ssh -T root@192.168.56.101 python3 - | Out-String)
if($LASTEXITCODE -ne 0){throw 'BUMBLEBEE_MASTERY_READ_FAILED; ATSUTI_IZVADI'}
$r=$text | ConvertFrom-Json
if($r.status -ne 'READ_ONLY_COMPLETE'){throw 'MASTERY_PROFILE_INCOMPLETE'}
$b=[Convert]::FromBase64String($r.zip_b64)
if($b.Length -ne $r.zip_bytes -or $b.Length -gt 8MB){throw 'MASTERY_ZIP_SIZE_DIFFERS'}
$h=[Security.Cryptography.SHA256]::Create()
try{$sha=([BitConverter]::ToString($h.ComputeHash($b))).Replace('-','').ToLowerInvariant()}finally{$h.Dispose()}
if($sha -ne $r.zip_sha256){throw 'MASTERY_ZIP_HASH_DIFFERS'}
$path=Join-Path $env:USERPROFILE ('Downloads\BumbleBee-Masteries-'+(Get-Date -Format yyyyMMdd-HHmmss)+'.zip')
[IO.File]::WriteAllBytes($path,$b)
'ZIP='+$path
'ATSUTI_SO_ZIP; PIESKIRUMI_VEL_NAV_MAINITI; NAV_PARSTARTESANAS'
